const paymentMarks={"redecompras":"assets/payment-marks/redecompras.png","elo": "assets/payment-marks/elo.svg", "amex": "assets/payment-marks/amex.svg", "hipercard": "assets/payment-marks/hipercard.svg", "pix": "assets/payment-marks/pix.svg", "pluxee": "assets/payment-marks/pluxee.svg", "ben": "assets/payment-marks/ben.svg", "cabal": "assets/payment-marks/cabal.svg", "up": "assets/payment-marks/up.svg", "alelo": "assets/payment-marks/alelo.svg", "vr": "assets/payment-marks/vr.svg", "ticket": "assets/payment-marks/ticket.svg", "sodexo": "assets/payment-marks/sodexo.webp", "greencard": "assets/payment-marks/greencard.webp", "safrapay": "assets/payment-marks/safrapay.svg", "rede": "assets/payment-marks/rede.png", "sumup": "assets/payment-marks/sumup.png", "ton": "assets/payment-marks/ton.svg", "infinitepay": "assets/payment-marks/infinitepay.ico", "visa": "assets/banks/visa.png", "mastercard": "assets/banks/mastercard.png", "stone": "assets/banks/stone.png", "getnet": "assets/banks/getnet.png", "cielo": "assets/banks/cielo.png", "pagbank": "assets/banks/pagbank.ico", "mercadopago": "assets/banks/mercadopago.png", "bkbank": "assets/payment-marks/bkbank.jpg", "maestro": "assets/payment-marks/maestro.svg"};
const paymentBrandPrefixes={"REDECOMPRAS":"redecompras","REDE COMPRAS":"redecompras","ELO": "elo", "VISA": "visa", "MASTERCARD": "mastercard", "HIPERCARD": "hipercard", "AMEX": "amex", "CABAL": "cabal", "SODEXO": "sodexo", "UP": "up", "ALELO": "alelo", "VR": "vr", "TICKET. RES": "ticket", "GREEN CARD": "greencard", "BEN VISA VALE": "ben", "BK BANK": "bkbank", "PIX": "pix", "MAESTRO": "maestro", "PLUXEE": "pluxee"};
const paymentOperatorPrefixes={"STONE": "stone", "GETNET": "getnet", "CIELO": "cielo", "PAGBANK": "pagbank", "SAFRAPAY": "safrapay", "REDE": "rede", "MERCADO PAGO": "mercadopago", "SUMUP": "sumup", "TON": "ton", "INFINITEPAY": "infinitepay"};
function getPaymentMark(key,name){if(!['bandeiras','operadoras'].includes(key))return null;const text=String(name||'').toUpperCase().trim();const pairs=Object.entries(key==='bandeiras'?paymentBrandPrefixes:paymentOperatorPrefixes).sort((a,b)=>b[0].length-a[0].length);const found=pairs.find(([prefix])=>text===prefix||text.startsWith(prefix+' '));return found?paymentMarks[found[1]]||null:null}
